<?php
namespace App\Modules\Customer\Application\UseCases;
use App\Models\CustomerAddress;use App\Modules\Auth\Domain\Contracts\AuthenticationServiceInterface;use App\Modules\Auth\Domain\Exceptions\AuthenticationException;use App\Modules\Customer\Domain\Contracts\CustomerFeaturesRepositoryInterface;use App\Modules\Customer\Domain\Exceptions\CustomerFeatureNotFoundException;
final class GetDefaultCustomerAddress {public function __construct(private readonly AuthenticationServiceInterface $auth,private readonly CustomerFeaturesRepositoryInterface $repo){}public function execute():CustomerAddress{$u=$this->auth->user();if(!$u)throw new AuthenticationException('Unauthenticated.');$a=$this->repo->defaultAddress($u->id);if(!$a)throw new CustomerFeatureNotFoundException('Default address',0);return $a;}}
